INSERT INTO `blogs` (`id`, `author_id`, `title`, `slug`, `thumbnail`, `summary`, `content`, `view_count`, `status`, `created_at`) VALUES
(1, 1, 'Top 5 Cấu Hình PC Gaming Đáng Mua Nhất Đầu Năm 2026', 'top-5-cau-hinh-pc-gaming-dang-mua-nhat-2026', 'assets/images/gaming-tower.jpg', 'Khám phá danh sách các bộ máy tính chơi game tối ưu nhất từ phân khúc phổ thông đến cao cấp, cân mượt mọi tựa game AAA ở độ phân giải 2K và 4K.', '<p>Năm 2026 chứng kiến sự bùng nổ của các tựa game thế giới mở đồ họa đỉnh cao với công nghệ Ray Tracing thế hệ mới. Để giúp các game thủ dễ dàng lựa chọn bộ máy ưng ý với mức ngân sách hợp lý nhất, PCMarket xin tổng hợp top 5 cấu hình PC Gaming đáng đầu tư nhất hiện nay.</p><h3>1. PC Gaming Phổ Thông: Intel Core i5 14400F + RTX 5050 8GB</h3><p>Đây là cấu hình quốc dân dành cho đại đa số game thủ chơi Esports như CS2, Valorant, Liên Minh Huyền Thoại và cả các tựa game nhập vai như Black Myth: Wukong ở độ phân giải Full HD.</p><h3>2. PC Gaming Trung Cấp: AMD Ryzen 7 5700X + RTX 5060 Ti 16GB</h3><p>Sự kết hợp hoàn hảo giữa 8 nhân 16 luồng và card đồ họa 16GB VRAM thế hệ mới giúp bạn chiến mượt mà ở màn hình 2K 144Hz mà không lo tràn bộ nhớ đồ họa.</p><h3>3. PC AI & Gaming Đỉnh Cao: Ultra 7 270K + RTX 5080 16GB</h3><p>Dành riêng cho những game thủ hardcore và nhà sáng tạo nội dung livestream, dựng phim 4K chuyên nghiệp.</p>', 1420, 1, NOW()),
(2, 1, 'Bí Quyết Chọn Nguồn Máy Tính (PSU) Chuẩn Nhất Cho Cấu Hình Khủng', 'bi-quyet-chon-nguon-may-tinh-psu-chuan-nhat', 'assets/images/workspace.jpg', 'Hướng dẫn tính toán công suất thực tế, lựa chọn chuẩn chứng nhận 80 Plus Bronze/Gold và đảm bảo an toàn tuyệt đối cho linh kiện của bạn.', '<p>Nguồn máy tính (Power Supply Unit - PSU) được ví như trái tim của cả bộ máy tính. Một bộ nguồn tốt không chỉ cung cấp dòng điện ổn định mà còn bảo vệ các linh kiện đắt tiền như CPU và Card đồ họa khỏi các sự cố chập cháy, sụt áp.</p><h3>Công thức tính công suất nguồn cần thiết</h3><p>Bạn chỉ cần cộng tổng công suất tiêu thụ (TDP) của CPU + VGA + khoảng 150W cho các linh kiện khác (Mainboard, RAM, SSD, Fan), sau đó nhân với hệ số an toàn 1.3 - 1.5.</p><h3>Chứng chỉ 80 Plus có ý nghĩa gì?</h3><p>Chứng chỉ 80 Plus xác nhận hiệu suất chuyển đổi điện năng của nguồn đạt trên 80%, giúp tiết kiệm điện và giảm nhiệt lượng tỏa ra trong thùng máy.</p>', 890, 1, NOW()),
(3, 1, 'So Sánh Intel Core Thế Hệ 14 và AMD Ryzen 7000 Series Cho Đồ Họa', 'so-sanh-intel-gen-14-va-amd-ryzen-7000-do-hoa', 'assets/images/workspace-monitor.jpg', 'Phân tích chi tiết hiệu năng dựng hình 3D, Render video Premiere / After Effects và khả năng đa nhiệm giữa hai ông lớn vi xử lý.', '<p>Trong phân khúc máy trạm đồ họa, cả Intel và AMD đều mang đến những giải pháp cực kỳ mạnh mẽ. Bài viết này sẽ phân tích khách quan hiệu năng thực tế dựa trên các bài test phần mềm phổ biến.</p><h3>Phần mềm dựng video: Adobe Premiere & DaVinci Resolve</h3><p>Nhờ công nghệ Intel QuickSync tích hợp, các chip Intel Core thế hệ 14 có lợi thế vượt trội khi preview và encode các định dạng video H.264/H.265 mượt mà không cần proxy.</p><h3>Phần mềm dựng hình 3D: Blender & 3ds Max</h3><p>AMD Ryzen với kiến trúc Zen 4 và bộ nhớ đệm 3D V-Cache mang lại hiệu năng tính toán đa nhân cực kỳ ấn tượng và mức tiêu thụ điện năng tối ưu hơn.</p>', 2150, 1, NOW());
